async function main() {
  console.log(`Importando ${insumos.length} insumos...`)
  let criados = 0, pulados = 0
  for (const item of insumos) {
    const existe = await prisma.componente.findUnique({ where: { codigoFabricante: item.codigo } })
    if (existe) { pulados++; continue }
    await prisma.componente.create({
      data: {
        codigoFabricante: item.codigo,
        descricao: item.descricao,
        fabricante: item.fabricante ?? null,
        categoria: item.categoria ?? null,
        unidadeMedida: item.unidade,
        precos: { create: { precoCusto: item.preco } },
      },
    })
    criados++
    if (criados % 100 === 0) console.log(`  ${criados} criados...`)
  }
  console.log(`✅ ${criados} insumos importados, ${pulados} já existiam`)
}

main()
  .catch((e) => { console.error(e); process.exit(1) })
  .finally(async () => { await prisma.$disconnect() })